-- Geometrías geo: municipios estado 14
-- Fuente: backend/app/data/geo/municipios/municipios_14_clean.geojson

create extension if not exists postgis;

alter table public.geo_municipios_mexico
  add column if not exists geom geometry(MultiPolygon, 4326),
  add column if not exists centroid geometry(Point, 4326);

with src as (
  select
    (row->>'clave_entidad') as clave_entidad,
    (row->>'clave_municipio') as clave_municipio,
    nullif((row->>'cvegeo'), '') as cvegeo,
