update public.geo_municipios_mexico m
set
  cvegeo = coalesce(src.cvegeo, m.cvegeo),
  geom = st_multi(st_setsrid(st_geomfromgeojson(src.geom_json::text), 4326)),
  centroid = st_pointonsurface(st_multi(st_setsrid(st_geomfromgeojson(src.geom_json::text), 4326))),
  actualizado_en = now()
from src
where m.clave_entidad = src.clave_entidad
  and m.clave_municipio = src.clave_municipio
  and src.geom_json is not null;

create index if not exists geo_municipios_mexico_geom_gix
  on public.geo_municipios_mexico using gist (geom);

create index if not exists geo_municipios_mexico_centroid_gix
  on public.geo_municipios_mexico using gist (centroid);
